9	const TABS = [['users', '← Accounts'], ['customer', 'Customer'], ['stress', 'Stress Test'], ['plan', 'Plan']];
10	const MODE_KEY = 'cushion:mode';
11	
12	function readMode() {
13	  try { return localStorage.getItem(MODE_KEY) === 'user' ? 'user' : 'admin'; } catch { return 'admin'; }
14	}
15	
16	export default function App() {
17	  const c = useCushion();
18	  const [view, setView] = useState('start');
19	  const [mode, setMode] = useState(readMode);
20	  const [accountInput, setAccountInput] = useState(String(c.account));
21	  const isAdmin = mode === 'admin';
22	  // Only admins can browse the account list; customers land on their own snapshot.
23	  const home = isAdmin ? 'users' : 'customer';
24	  const tabs = isAdmin ? TABS : TABS.filter(([v]) => v !== 'users');
25	
26	  // The stylesheet switches layouts on body[data-view=...].
27	  useEffect(() => { document.body.dataset.view = view; }, [view]);
28	
29	  function show(next) {
30	    setView(VIEWS.includes(next) && (isAdmin || next !== 'users') ? next : home);
31	    window.scrollTo({ top: 0, behavior: 'instant' });
32	  }
33	
34	  function toggleMode() {
35	    const next = isAdmin ? 'user' : 'admin';
36	    setMode(next);
37	    try { localStorage.setItem(MODE_KEY, next); } catch { /* per-viewer convenience only */ }
38	    if (next === 'user' && view === 'users') setView('customer');
39	  }
40	
41	  function openAccount(id) {
42	    setAccountInput(String(id));
43	    if (!c.busy) c.loadAccount(id);
44	    show('customer');
45	  }
46	
47	  return (
48	    <>
49	      {view === 'start' && <Welcome onDone={() => show(home)} />}
50	      <div id="app-shell" hidden={view === 'start'}>
51	        <header>
52	          <a className="brand" href="/" aria-label="Cushion home" onClick={e => { e.preventDefault(); show(home); }}>
53	            <img className="brand-pillow" src="/pillow.PNG" alt="" /> Cushion
54	          </a>
55	          <span className="header-note">CUSHION / RESILIENCE REWIRED</span>
56	          <button type="button" className="mode-switch" role="switch" aria-checked={isAdmin}
57	            aria-label="Admin mode" onClick={toggleMode}>
