160	  const [w, setW] = useState(0);
161	  useEffect(() => {
162	    const el = ref.current;
163	    const ro = new ResizeObserver(([e]) => setW(e.contentRect.width));
164	    ro.observe(el);
165	    return () => ro.disconnect();
166	  }, []);
167	  const mid = w / 2;
168	  const xs = Array.from({ length: n }, (_, k) => ((k + 0.5) / n) * w);
169	  return (
170	    <svg ref={ref} className="lin-fan" viewBox={`0 0 ${w || 1} ${FAN_H}`} aria-hidden="true">
171	      {w > 0 && xs.map(x => (
172	        <path key={x}
173	          d={dir === 'out' ? `M${mid} 0 C${mid} 24 ${x} 20 ${x} ${FAN_H}` : `M${x} 0 C${x} 24 ${mid} 20 ${mid} ${FAN_H}`} />
174	      ))}
175	    </svg>
176	  );
