179	export default function DataLineage({ baseline, account, onBack }) {
180	  const [revealed, setRevealed] = useState(1);   // beats shown; the newest one is still "running"
181	  const tail = useRef(null);
182	  const { steps, total } = baseline ? withBeats(buildSteps(baseline, account)) : { steps: [], total: 0 };
183	
184	  // One beat every BEAT_MS; the extra final beat marks the last step done.
185	  useEffect(() => {
186	    if (!total || revealed > total) return undefined;
187	    const t = setTimeout(() => setRevealed(r => r + 1), BEAT_MS);
188	    return () => clearTimeout(t);
189	  }, [revealed, total]);
190	
191	  useEffect(() => { tail.current?.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }, [revealed]);
192	
193	  const status = beat => (beat < revealed - 1 ? 'done' : 'active');
194	  const shown = beat => beat < revealed;
195	
196	  return (
197	    <main className="lineage-screen">
198	      <div className="lineage-head">
199	        <button type="button" className="lineage-back" onClick={onBack}>← Back</button>
200	        <div>
201	          <p className="eyebrow">DATA LINEAGE · ACCOUNT {account}</p>
202	          <h1>How did we get this data?</h1>
203	          <p className="sub">Every number on the Customer page comes from this account’s monthly records and loan record. Here is each step, in order.</p>
204	        </div>
205	        <button type="button" className="lineage-replay" onClick={() => setRevealed(1)}
206	          disabled={revealed <= total}>Replay ↻</button>
207	      </div>
208	
209	      {!baseline ? <p className="empty">Loading account…</p> : (
210	        <ol className="lineage" aria-live="polite">
211	          {steps.map((s, i) => {
212	            if (!shown(s.beat)) return null;
213	            if (s.section) {
214	              return (
215	                <li key={i} ref={s.beat === revealed - 1 ? tail : undefined}>
216	                  <div className="lin-link" aria-hidden="true" />
217	                  <h2 className="lin-section">{s.section}</h2>
218	                </li>
219	              );
220	            }
221	            if (!s.columns) {
222	              return (
223	                <li key={i} ref={s.beat === revealed - 1 ? tail : undefined}>
224	                  {i > 0 && <div className="lin-link" aria-hidden="true" />}
225	                  <Node status={status(s.beat)} {...s} />
226	                </li>
227	              );
228	            }
229	            const merged = shown(s.mergeBeat);
230	            return (
231	              <li key={i} className="lin-split" ref={[s.beat, s.mergeBeat].includes(revealed - 1) ? tail : undefined}>
232	                <Fan n={s.columns.length} dir="out" />
233	                <div className="lin-columns" style={{ gridTemplateColumns: `repeat(${s.columns.length}, minmax(0, 1fr))` }}>
234	                  {s.columns.map(col => (
235	                    <div key={col.title} className="lin-column"><Node branch status={status(s.beat)} {...col} /></div>
236	                  ))}
237	                </div>
238	                {merged && <Fan n={s.columns.length} dir="in" />}
239	                {merged && <Node status={status(s.mergeBeat)} {...s.merge} />}
240	              </li>
241	            );
242	          })}
243	        </ol>
244	      )}
245	    </main>
246	  );
247	}
