27	// Baseline runway computed in the browser when no plan has been calculated yet.
28	export function baselineRunway(b) {
29	  const gap = b.spending - b.income;
30	  return {
31	    income: b.income,
32	    spending: b.spending,
33	    buffer: b.buffer,
34	    runway_months: b.buffer <= 0 ? 0 : gap <= 0 ? 'no_shortfall' : Math.min(b.buffer / gap, 120).toFixed(1),
35	    runway_capped: gap > 0 && b.buffer / gap > 120,
36	  };
37	}
