39	// Plain-language bullet list of what a scenario changes, shown before it is applied.
40	export function describeChanges(s) {
41	  const out = [];
42	  const months = n => `${n} month${n === 1 ? '' : 's'}`;
43	  if (s.parts?.length) {
44	    // Stacked scenario: each part keeps its own duration.
45	    let longest = 0;
46	    for (const p of s.parts) {
47	      const window = p.scenario_duration_months || p.income_duration_months;
48	      longest = Math.max(longest, window || 0);
49	      for (const line of describeChanges(p)) {
50	        if (line.startsWith('Assessed over') || line === 'No changes from your baseline') continue;
51	        const timed = /^(No income|Income) /.test(line) || line.endsWith(' one-off');
52	        out.push(window && !timed ? `${line} for ${months(window)}` : line);
53	      }
54	    }
55	    if (!out.length) out.push('No changes from your baseline');
56	    if (longest) out.push(`Assessed over ${months(longest)}; each change lasts only for its own duration`);
57	    return out;
58	  }
59	  if (s.income_multiplier != null && s.income_multiplier !== 1) {
60	    const pct = Math.round(s.income_multiplier * 1000) / 10;
61	    out.push(pct === 0
62	      ? `No income for ${months(s.income_duration_months)}`
63	      : `Income ${pct < 100 ? 'drops' : 'rises'} to ${pct}% of normal for ${months(s.income_duration_months)}`);
64	  }
65	  if (s.household_bills_pct_change) {
66	    out.push(`Household bills ${s.household_bills_pct_change > 0 ? 'rise' : 'fall'} ${Math.abs(s.household_bills_pct_change)}%`);
67	  }
68	  for (const c of s.one_off_costs || []) out.push(`${c.label}: ${preciseCash(c.amount_dollars)} one-off`);
69	  for (const c of s.recurring_costs || []) {
70	    out.push(`${c.label}: ${c.monthly_change > 0 ? '+' : '−'}${preciseCash(Math.abs(c.monthly_change))}/month`);
71	  }
72	  if (!out.length) out.push('No changes from your baseline');
73	  if (s.scenario_duration_months) out.push(`Assessed over ${months(s.scenario_duration_months)}`);
74	  return out;
75	}
