137	"""Anonymous, deterministic cohort comparisons; a spending benchmark is not a budget."""
138	import math
139	from statistics import median
140	
141	MIN_PEERS = 10
142	MAX_PEERS = 50
143	COMPARISONS = [
144	    ('spending','Total monthly outflow','Review the biggest recurring payments first. This total overlaps the channels below; do not add the gaps together.'),
145	    ('household_bills','Household bills','Compare providers and recurring charges. Housing and utilities may be essential; only test changes you can actually make.'),
146	    ('cash_withdrawals','Cash withdrawals','Check what the cash pays for. Identify optional purchases before choosing any reduction.'),
147	    ('card_withdrawals','Card withdrawals','Review the underlying purchases before deciding whether any amount can be reduced.'),
148	    ('transfers_out_other','Other outgoing transfers','Check the recipients and purpose. Transfers may cover bills, family support or movement between your own accounts.'),
149	]
150	
151	
152	def compare_peers(account_id, records):
153	    target=records.get(account_id)
154	    if target is None:
155	        from .db import AccountNotFound
156	        raise AccountNotFound(account_id)
157	    required=['income','fixed_costs','loan_payment','spending']
158	    def valid(row):
159	        return all(math.isfinite(row.get(k,float('nan'))) and row[k]>=0 for k in required)
160	    method={'income_tolerance_pct':30,'fixed_cost_tolerance_pct':40,'loan_payment_tolerance_pct':40,
161	            'cost_tolerance_floor':200,'minimum_peers':MIN_PEERS,'maximum_peers':MAX_PEERS,
162	            'description':'Closest accounts within 30% of income and 40% of fixed costs and loan payments (a $200 tolerance floor for costs), with the same active-loan-payment status. The selected account is excluded.'}
163	    if not valid(target):
164	        return {'status':'unavailable','peer_count':0,'method':method,'comparisons':[],
165	                'message':'This account does not have enough valid matching data for a comparison.'}
166	    candidates=[]
167	    for other_id,row in records.items():
168	        if other_id==account_id or not valid(row):continue
169	        if (row['loan_payment']>0)!=(target['loan_payment']>0):continue
170	        scales=[max(target['income']*.30,1),max(target['fixed_costs']*.40,200),max(target['loan_payment']*.40,200)]
171	        distances=[abs(row[k]-target[k])/scale for k,scale in zip(['income','fixed_costs','loan_payment'],scales)]
172	        if all(d<=1 for d in distances):candidates.append((sum(d*d for d in distances),other_id,row))
173	    candidates.sort(key=lambda x:(x[0],x[1]))
