197	def assess(initial, budgets):
198	    balance = initial
199	    minimum = initial
200	    cumulative_gap = 0
201	    peak_gap = 0
202	    improvement = 0
203	    rows = [{'month': 0, 'balance': round(initial, 2)}]
204	    for month, budget in enumerate(budgets, 1):
205	        income, spending = budget['income'], budget['spending']
206	        if spending < 0:
207	            raise ValueError(f'Spending reductions exceed spending in month {month}')
208	        cumulative_gap += spending - income
209	        peak_gap = max(peak_gap, cumulative_gap)
210	        improvement = max(improvement, (cumulative_gap - max(initial, 0)) / month)
211	        balance += income - spending
212	        minimum = min(minimum, balance)
213	        rows.append({'month': month, 'income': round(income, 2), 'spending': round(spending, 2),
214	                     'net_change': round(income-spending, 2), 'balance': round(balance, 2)})
215	    return {'rows': rows, 'ending': balance, 'minimum': minimum,
216	            'peak_gap': max(0, peak_gap), 'improvement': max(0, improvement),
217	            'covered': minimum >= -1e-8}
