220	def monthly_budgets(baseline, shock, horizon):
221	    overrides = shock.effect_durations
222	    def active(key, month, fallback=None):
223	        return month <= overrides.get(key, fallback or horizon)
224	    result = []
225	    for month in range(1, horizon+1):
226	        income = baseline['income']
227	        if shock.income_multiplier is not None and active('income',month,shock.income_duration_months):
228	            income *= shock.income_multiplier
229	        spending = baseline['spending']
230	        if shock.household_bills_pct_change is not None and active('bills',month):
231	            spending += baseline['household_bills']*shock.household_bills_pct_change/100
232	        if shock.spending_pct_change is not None and active('spending',month):
233	            spending += baseline['spending']*shock.spending_pct_change/100
234	        for i,cost in enumerate(shock.recurring_costs):
235	            if active(f'category_{i}',month,cost.duration_months):
236	                spending += cost.monthly_change
237	        result.append({'income':income,'spending':spending})
238	    return result
