"""Peer comparison: a deterministic cohort by income, fixed costs and loan payment. No database needed."""
import pytest
from fastapi.testclient import TestClient

from app.db import AccountNotFound, get_session
from app.finance.peers import MAX_PEERS, compare_peers
from app.main import app


def _row(income=4000.0, fixed=1200.0, loan=0.0, spending=3500.0, bills=900.0, cash=300.0, card=800.0,
         transfers=200.0):
    return {"income": income, "spending": spending, "household_bills": bills, "fixed_costs": fixed,
            "loan_payment": loan, "cash_withdrawals": cash, "card_withdrawals": card,
            "transfers_out_other": transfers}


def test_unknown_account_raises():
    with pytest.raises(AccountNotFound):
        compare_peers(1, {2: _row()})


def test_invalid_target_is_unavailable():
    result = compare_peers(1, {1: _row(income=float("nan")), 2: _row()})
    assert result["status"] == "unavailable" and result["comparisons"] == []


def test_too_few_matches_gives_no_suggestions():
    records = {1: _row(), **{i: _row(income=4000 + 50 * i) for i in range(2, 7)}}
    result = compare_peers(1, records)
    assert result["status"] == "insufficient_peers"
    assert result["peer_count"] == 5 and result["comparisons"] == []


def test_cohort_excludes_self_other_loan_status_and_distant_income():
    records = {1: _row(spending=4200.0, cash=900.0)}
    for i in range(2, 32):
        records[i] = _row(income=4000 + 10 * i)       # 30 close peers, no loan
    records[100] = _row(loan=500.0)                   # has a loan payment: different status, excluded
    records[101] = _row(income=9000.0)                # more than 30% away on income, excluded
    result = compare_peers(1, records)
    assert result["status"] == "ok"
    assert result["peer_count"] == 30 and result["eligible_count"] == 30
    by_key = {c["key"]: c for c in result["comparisons"]}
    assert by_key["spending"]["above_median"] and by_key["spending"]["difference"] == pytest.approx(700.0)
    assert by_key["spending"]["pct_above_median"] == pytest.approx(20.0)
    assert by_key["cash_withdrawals"]["pct_above_median"] == pytest.approx(200.0)
    assert not by_key["household_bills"]["above_median"]
    assert by_key["household_bills"]["pct_above_median"] is None
    assert all(c["can_sum_with_other_gaps"] is False for c in result["comparisons"])


def test_cohort_is_capped_at_the_closest_matches():
    records = {1: _row()}
    for i in range(2, 2 + MAX_PEERS + 20):
        records[i] = _row(income=4000 + 5 * i)
    result = compare_peers(1, records)
    assert result["peer_count"] == MAX_PEERS and result["eligible_count"] == MAX_PEERS + 20


def test_peers_endpoint_without_database_is_503(no_database):
    try:
        with TestClient(app) as client:
            assert client.get("/api/accounts/20111/peers").status_code == 503
    finally:
        app.dependency_overrides.clear()


def test_peers_endpoint_with_database(session):
    app.dependency_overrides[get_session] = lambda: session
    try:
        with TestClient(app) as client:
            body = client.get("/api/accounts/20111/peers").json()
            assert body["status"] in {"ok", "insufficient_peers"}
            assert body["method"]["minimum_peers"] == 10
            assert client.get("/api/accounts/1/peers").status_code == 404
    finally:
        app.dependency_overrides.clear()

import { useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { cash, compactCash, preciseCash } from '../format.js';

// Plot area inside the 600 x 296 viewBox.
const LEFT = 76, RIGHT = 568, TOP = 34, BOTTOM = 242;

// Month-by-month buffer: the engine's path for stacked scenarios with different durations,
// otherwise a straight line from the buffer after immediate costs to the assessed end balance.
function buildSeries(plan) {
  const d = plan.duration_assessment;
  const a = plan.after_shock;
  if (d.buffer_path) return d.buffer_path.map((value, month) => ({ month, value }));
  const net = (d.ending_buffer - a.buffer) / d.months;
  return Array.from({ length: d.months + 1 }, (_, i) => ({ month: i, value: a.buffer + i * net }));
}

const crossing = (prev, next) => prev.month + prev.value / (prev.value - next.value);

// Add a point wherever the line crosses $0, so the funded and unfunded parts can be drawn apart,
// and find the month the savings first run out.
function splitAtZero(values) {
  const points = [values[0]];
  let exhausted = values[0].value <= 0 ? 0 : null;
  for (let i = 1; i < values.length; i++) {
    const prev = values[i - 1];
    const next = values[i];
    if (prev.value * next.value < 0) points.push({ month: crossing(prev, next), value: 0 });
    if (exhausted === null && next.value <= 0) exhausted = crossing(prev, next);
    points.push(next);
  }
  return { points, exhausted };
}

// Consecutive runs of points on one side of $0; a point on the line belongs to both sides.
function runs(points, sign) {
  const out = [];
  let current = [];
  for (const p of points) {
    if (sign * p.value >= 0) current.push(p);
    else { if (current.length) out.push(current); current = []; }
  }
  if (current.length) out.push(current);
  return out;
}

const Row = ({ label, children }) => <div><dt>{label}</dt><dd>{children}</dd></div>;

// How the buffer moves through the scenario: area chart with the unfunded part dashed in red,
// a marker where savings run out, and a tooltip per month. Replaces the earlier plain line chart.
export default function Projection({ plan }) {
  const gradientId = 'buffer-fill-' + useId().replace(/[^a-zA-Z0-9_-]/g, '');
  const d = plan.duration_assessment;
  const a = plan.after_shock;
  const n = d.months;
  const values = buildSeries(plan);
  const end = values[n].value;
  const top = Math.max(1, ...values.map(v => v.value));
  const bottom = Math.min(0, ...values.map(v => v.value));
  const pad = (top - bottom) * 0.14;
  const hi = top + pad;
  const lo = bottom < 0 ? bottom - pad : 0;
  const x = m => LEFT + (m / n) * (RIGHT - LEFT);
  const y = v => TOP + ((hi - v) / (hi - lo)) * (BOTTOM - TOP);

  const { points, exhausted } = splitAtZero(values);
  const path = pts => pts.map((p, i) => `${i ? 'L' : 'M'}${x(p.month).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ');
  const area = pts => (pts.length > 1 ? `${path(pts)} L${x(pts.at(-1).month)},${y(0)} L${x(pts[0].month)},${y(0)} Z` : '');
  const positive = runs(points, 1);
  const negative = runs(points, -1);
  const ticks = n <= 12
    ? Array.from({ length: n + 1 }, (_, i) => i)
    : [...new Set([0, ...Array.from({ length: 6 }, (_, i) => Math.round((n * (i + 1)) / 6))])];
  // Grid lines, skipping the one that would sit on top of the $0 line.
  const grid = Array.from({ length: 5 }, (_, i) => lo + ((hi - lo) * i) / 4).filter(v => Math.abs(v) > (hi - lo) * 0.03);
  const shortfall = exhausted !== null;
  const status = shortfall
    ? `Savings run out ${exhausted === 0 ? 'immediately' : 'around month ' + exhausted.toFixed(1)}`
    : `Buffer lasts through month ${n}`;

  // Tooltip: one visible box positioned over the hovered/focused point (the SVG <title> popup is browser-dependent).
  const [tip, setTip] = useState(null);
  const tipRef = useRef(null);
  useLayoutEffect(() => {
    const el = tipRef.current;
    if (!el || !tip) return;
    const t = el.getBoundingClientRect();
    const r = tip.rect;
    el.style.left = `${Math.max(8, Math.min(window.innerWidth - t.width - 8, r.left + r.width / 2 - t.width / 2))}px`;
    el.style.top = `${Math.max(8, r.top - t.height - 10)}px`;
  }, [tip]);
  useEffect(() => {
    if (!tip) return undefined;
    const hide = () => setTip(null);
    const onKey = e => { if (e.key === 'Escape') hide(); };
    window.addEventListener('scroll', hide, true);
    document.addEventListener('keydown', onKey);
    return () => { window.removeEventListener('scroll', hide, true); document.removeEventListener('keydown', onKey); };
  }, [tip]);
  const show = (e, label) => setTip({ label, rect: e.currentTarget.getBoundingClientRect() });
  const hide = () => setTip(null);

  // "How this balance is calculated": the plan's own figures, before any confirmed backup actions.
  const ap = plan.action_plan;
  const startBuffer = ap?.goal.current_buffer ?? plan.baseline.buffer;
  const oneOff = ap?.backup.one_off_cost ?? a.one_off_costs ?? 0;
  const afterCosts = ap?.backup.buffer_after_expense ?? a.buffer;
  const incomeAfter = ap ? ap.backup.income_after_actions - ap.backup.confirmed_extra_income : a.income;
  const spendingAfter = ap ? ap.backup.spending_after_actions + ap.backup.confirmed_monthly_cut : a.spending;
  const net = incomeAfter - spendingAfter;

  return (
    <section className="chart projection">
      <div className="projection-heading">
        <div>
          <h3>Your savings over time</h3>
          <p>What happens if this scenario continues for {n} months?</p>
        </div>
        <span className={'projection-pill' + (shortfall ? ' shortfall' : '')}>{shortfall ? 'Funding gap' : 'Covered'}</span>
      </div>
      <div className="projection-stats">
        <div><small>After immediate costs</small><strong>{cash(a.buffer)}</strong></div>
        <span aria-hidden="true">→</span>
        <div>
          <small>{end < 0 ? 'Unfunded by' : 'Projected at'} month {n}</small>
          <strong className={end < 0 ? 'projection-loss' : undefined}>{cash(Math.abs(end))}</strong>
        </div>
      </div>
      <svg viewBox="0 0 600 296" role="img"
        aria-label={`Savings projection: starts at ${cash(a.buffer)}, ends at ${cash(end)} after ${n} months. ${status}.`}>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#f58220" stopOpacity=".24" />
            <stop offset="100%" stopColor="#f58220" stopOpacity=".02" />
          </linearGradient>
        </defs>
        {grid.map(v => (
          <g key={v}>
            <line x1={LEFT} x2={RIGHT} y1={y(v)} y2={y(v)} className="projection-grid" />
            <text x={LEFT - 12} y={y(v) + 4} textAnchor="end">{compactCash(v)}</text>
          </g>
        ))}
        <path d={positive.map(area).join(' ')} fill={`url(#${gradientId})`} />
        <path d={negative.map(area).join(' ')} fill="#c8344b" fillOpacity=".08" />
        <line x1={LEFT} x2={RIGHT} y1={y(0)} y2={y(0)} className="projection-zero" />
        <text x={LEFT - 12} y={y(0) + 4} textAnchor="end">$0</text>
        <path d={positive.map(path).join(' ')} className="projection-line" />
        <path d={negative.map(path).join(' ')} className="projection-line negative" />
        {values.map(p => {
          const label = `${p.month === 0 ? 'Now' : 'Month ' + p.month} · ${cash(Math.abs(p.value))}${p.value < 0 ? ' unfunded' : ' remaining'}`;
          return (
            <g key={p.month} className="projection-point" tabIndex={0} role="button" aria-label={label}
              onPointerEnter={e => show(e, label)} onPointerLeave={hide} onFocus={e => show(e, label)} onBlur={hide}
              onClick={e => show(e, label)}
              onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); show(e, label); } }}>
              <circle cx={x(p.month)} cy={y(p.value)} r="15" fill="transparent" />
              <circle cx={x(p.month)} cy={y(p.value)} r={p.month === 0 || p.month === n ? 5 : 3}
                fill={p.value < 0 ? '#c8344b' : '#f58220'} stroke="white" strokeWidth="2" />
            </g>
          );
        })}
        {shortfall && exhausted > 0 && (
          <circle cx={x(exhausted)} cy={y(0)} r="6" fill="white" stroke="#c8344b" strokeWidth="2">
            <title>Savings exhausted around month {exhausted.toFixed(1)}</title>
          </circle>
        )}
        {ticks.map(m => <text key={m} x={x(m)} y="268" textAnchor="middle">{m === 0 ? 'Now' : 'Mo ' + m}</text>)}
        <text x="322" y="291" textAnchor="middle">Months after shock</text>
      </svg>
      {tip && <div className="balance-tooltip" role="tooltip" ref={tipRef}>{tip.label}</div>}
      <div className={'projection-caption' + (shortfall ? ' projection-loss' : '')}><span className="projection-dot" />{status}</div>
      <p className="projection-note">
        {end < 0 && 'The dashed red line shows spending that savings cannot cover. '}
        {d.buffer_path ? 'Each change lasts only for its own duration. ' : 'Income and spending stay constant over this period. '}
        Hover, tap, or focus a point for its balance.
      </p>
      <details className="balance-calculation">
        <summary>How this balance is calculated</summary>
        <p>The starting buffer is the average daily account balance over the last six recorded months. It estimates funds already available; it is not money added every month.</p>
        <dl>
          <Row label="Historical starting buffer">{preciseCash(startBuffer)}</Row>
          <Row label="Immediate scenario costs">− {preciseCash(oneOff)}</Row>
          <Row label="Available after immediate costs">{preciseCash(afterCosts)}</Row>
          <Row label="Monthly income after the shock">{preciseCash(incomeAfter)}</Row>
          <Row label="Monthly spending after the shock">− {preciseCash(spendingAfter)}</Row>
          <Row label={d.buffer_path ? 'Month-one net change' : 'Net monthly change'}>{preciseCash(net)}</Row>
        </dl>
        {d.buffer_path ? (
          <>
            <div className="monthly-table-wrap">
              <table className="comparison">
                <thead><tr><th>Month</th><th>Change</th><th>Balance</th></tr></thead>
                <tbody>
                  {values.slice(1).map((p, i) => (
                    <tr key={p.month}><td>{p.month}</td><td>{preciseCash(p.value - values[i].value)}</td><td>{preciseCash(p.value)}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p>Each month's balance = the previous balance + that month's income − that month's spending. Temporary changes stop after their own duration.</p>
          </>
        ) : (
          <>
            <p className="balance-equation">Month {n}: {cash(a.buffer)} + ({cash(net)} × {n}) = <strong>{cash(end)}</strong></p>
            <p>Each month, income replenishes the balance and spending draws it down. The historical buffer is not added again.</p>
          </>
        )}
      </details>
    </section>
  );
}

import { useEffect, useRef, useState } from 'react';
import { api, preciseCash } from '../format.js';

const cache = new Map();   // account id -> result, so recalculating a plan does not refetch

function Method({ method }) {
  return (
    <details>
      <summary>How these accounts were matched</summary>
      <p>{method.description}</p>
      <p>The comparison uses monthly account metrics, not individual purchase categories. Loan matching uses payment amounts, not loan balances or interest rates. Household size and location are not part of the match.</p>
    </details>
  );
}

// Spending benchmarks against the closest accounts by income, fixed costs and loan payment.
// With a backup plan on screen, a reviewed reduction can be copied into its "confirmed spending reduction".
export default function PeerComparison({ account, spendingCap, currentCut, onUseCut }) {
  const [data, setData] = useState(() => cache.get(account) ?? null);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');
  const choice = useRef(null);

  useEffect(() => {
    let active = true;
    setError('');
    setStatus('');
    if (cache.has(account)) { setData(cache.get(account)); return undefined; }
    setData(null);
    api(`/api/accounts/${account}/peers`)
      .then(result => { cache.set(account, result); if (active) setData(result); })
      .catch(e => { if (active) setError(e.message); });
    return () => { active = false; };
  }, [account]);

  if (error) {
    return (
      <section className="peer-comparison" aria-labelledby="peer-comparison-title">
        <h3 id="peer-comparison-title">Peer comparison unavailable</h3>
        <p>{error}</p>
        <p>Your own account plan is still available.</p>
      </section>
    );
  }
  if (!data) {
    return (
      <section className="peer-comparison" aria-labelledby="peer-comparison-title" aria-busy="true">
        <h3 id="peer-comparison-title">Find areas to review</h3>
        <p>Finding accounts with similar income, fixed costs and loan payments…</p>
      </section>
    );
  }
  if (data.status !== 'ok') {
    return (
      <section className="peer-comparison" aria-labelledby="peer-comparison-title">
        <p className="eyebrow">PEER COMPARISON</p>
        <h3 id="peer-comparison-title">Find areas to review</h3>
        <p>{data.message}</p>
        <Method method={data.method} />
      </section>
    );
  }

  const above = data.comparisons.filter(c => c.above_median).sort((a, b) => b.difference - a.difference);

  function useCut() {
    const input = choice.current;
    if (!input?.reportValidity()) return;
    const value = Number(input.value);
    onUseCut(value);
    setStatus(`${preciseCash(value)}/month entered in your backup budget. Select “Recalculate my plans” to test it.`);
  }

  return (
    <section className="peer-comparison" aria-labelledby="peer-comparison-title">
      <p className="eyebrow">PEER COMPARISON · {data.peer_count} SIMILAR ACCOUNTS</p>
      <h3 id="peer-comparison-title">Where could you spend less?</h3>
      <p>{data.message}</p>
      <div className="peer-table-wrap">
        <table className="comparison">
          <thead><tr><th>Monthly area</th><th>You</th><th>Peer median</th><th>Difference</th></tr></thead>
          <tbody>
            {data.comparisons.map(c => (
              <tr key={c.key}>
                <td>{c.label}</td>
                <td>{preciseCash(c.your_amount)}</td>
                <td>{preciseCash(c.peer_median)}</td>
                <td className={c.above_median ? 'above-median' : undefined}>{c.above_median ? '+' : ''}{preciseCash(c.difference)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {above.length ? (
        <>
          <h4>Start by reviewing these areas</h4>
          <div className="peer-review-list">
            {above.map(c => (
              <article key={c.key}>
                <strong>{c.label} · {preciseCash(c.difference)} above the median</strong>
                <p>{c.review}</p>
              </article>
            ))}
          </div>
          {onUseCut && (
            <div className="peer-budget-choice">
              {/* No name attribute: this input must not be posted with the planning form. */}
              <label>After reviewing your spending, how much could you reduce per month?
                <input ref={choice} type="number" min="0" max={spendingCap} step="0.01" defaultValue={currentCut ?? 0} />
              </label>
              <button type="button" onClick={useCut}>Use this in my backup budget</button>
              <p role="status">{status}</p>
            </div>
          )}
        </>
      ) : (
        <p>No measured area is above this peer median. That does not guarantee the current budget is affordable; use your own costs and goal to decide what to change.</p>
      )}
      <p className="peer-note">An above-median amount is a review opportunity, not proof of overspending. Total outflow includes overlapping channels; do not add their gaps together. No cuts are applied automatically.</p>
      <Method method={data.method} />
    </section>
  );
}

import { cash, compactCash } from '../format.js';

const pct = value => value == null ? 'Not recorded' : `${(value * 100).toFixed(0)}%`;
const clamp = value => Math.max(0, Math.min(100, value));
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const loanStatus = status => ({
  A: 'Loan paid off',
  B: 'Loan paid off with an unpaid balance recorded',
  C: 'Active loan. No debt recorded so far.',
  D: 'Active loan. Debt recorded in the past.',
}[status] || 'No loan record');

function Signal({ label, value, detail, tone = '', children }) {
  return (
    <article className={`account-signal${tone ? ` ${tone}` : ''}`}>
      <small>{label}</small>
      <strong>{value}</strong>
      {detail && <span>{detail}</span>}
      {children}
    </article>
  );
}

// A thin bar with optional target marks (percent positions), shown under a signal's text.
function Meter({ fill, marks = [], scale, label }) {
  return (
    <div className="signal-meter" role="img" aria-label={label}>
      <div className="meter-track">
        <span className="meter-fill" style={{ width: `${clamp(fill)}%` }} />
        {marks.map(m => <i key={m} className="meter-mark" style={{ left: `${m}%` }} aria-hidden="true" />)}
      </div>
      {scale && <div className="meter-scale">{scale.map(s => <span key={s}>{s}</span>)}</div>}
    </div>
  );
}

// A share of something, drawn as a small bar under a fact.
function FactMeter({ value, label, warning }) {
  return (
    <i className={`fact-meter${warning ? ' warning' : ''}`} role="img" aria-label={label}>
      <span style={{ width: `${clamp(value)}%` }} />
    </i>
  );
}

function MonthlyHistory({ rows }) {
  if (!rows?.length) return null;
  const max = Math.max(1, ...rows.flatMap(row => [row.money_in, row.money_out]));
  return (
    <section className="history-chart" aria-labelledby="history-chart-title">
      <div className="insight-subheading">
        <h3 id="history-chart-title">Money coming in and going out</h3>
        <span>Most recent {rows.length} months on record</span>
      </div>
      <div className="history-legend"><span>Money in</span><span>Money out</span></div>
      <div className="history-bars">
        {rows.map(row => (
          <div className="history-month" key={row.month} title={`${row.month}: money in ${cash(row.money_in)}, money out ${cash(row.money_out)}`}>
            <div className="history-bar-pair">
              <span className="history-in" style={{ height: `${Math.max(3, row.money_in / max * 100)}%` }} />
              <span className="history-out" style={{ height: `${Math.max(3, row.money_out / max * 100)}%` }} />
            </div>
            <small>{row.month.slice(5)}</small>
          </div>
        ))}
      </div>
      <div className="history-caption"><span>{rows[0].month}</span><span>{rows.at(-1).month}</span></div>
    </section>
  );
}

// Month-end balance as a line, with the $0 line dashed. A month-end value is a snapshot.
function BalanceHistory({ rows }) {
  if (!rows?.length) return null;
  const width = 720, height = 220, left = 56, right = 12, top = 18, bottom = 38;
  const plotW = width - left - right;
  const plotH = height - top - bottom;
  const balances = rows.map(row => row.month_end_balance);
  const min = Math.min(0, ...balances);
  const max = Math.max(0, ...balances);
  const pad = Math.max((max - min) * 0.08, 1);
  const lo = min - pad;
  const hi = max + pad;
  const y = v => top + plotH - ((v - lo) / (hi - lo)) * plotH;
  const step = plotW / rows.length;
  const x = i => left + step * (i + 0.5);
  return (
    <section className="history-chart" aria-labelledby="balance-chart-title">
      <div className="insight-subheading">
        <h3 id="balance-chart-title">Month-end balance</h3>
        <span>Recorded balance over time</span>
      </div>
      <div className="history-legend balance-legend"><span>Balance</span><span>$0 line</span></div>
      <svg className="balance-chart" viewBox={`0 0 ${width} ${height}`} role="img"
        aria-label={`Month-end balance for the last ${rows.length} recorded months; the dashed line marks zero`}>
        <line className="chart-gridline" x1={left} y1={top} x2={width - right} y2={top} />
        <line className="chart-zero" x1={left} y1={y(0)} x2={width - right} y2={y(0)} />
        <text className="chart-label" x={left - 8} y={top + 4} textAnchor="end">{compactCash(max)}</text>
        <text className="chart-label" x={left - 8} y={top + plotH} textAnchor="end">{compactCash(min)}</text>
        <polyline className="balance-line" points={rows.map((row, i) => `${x(i)},${y(row.month_end_balance)}`).join(' ')} />
        {rows.map((row, i) => (
          <circle key={row.month} className="balance-point" cx={x(i)} cy={y(row.month_end_balance)} r="3.5">
            <title>{`${row.month} month-end balance: ${cash(row.month_end_balance)}`}</title>
          </circle>
        ))}
        {rows.map((row, i) => i % 2 === 0 && (
          <text key={row.month} className="chart-label" x={x(i)} y={height - 12} textAnchor="middle">
            {MONTHS[Number(row.month.slice(5, 7)) - 1] || row.month}
          </text>
        ))}
      </svg>
      <small className="history-note">A month-end value is a snapshot; it does not show every balance change during the month.</small>
    </section>
  );
}

// Where this loan sits among ongoing loans: three bands, one marker. Not a probability of default.
function LoanRiskScale({ band, size }) {
  const key = band.toLowerCase();
  if (!['lower', 'middle', 'higher'].includes(key)) return null;
  return (
    <div className={`loan-risk-scale risk-${key}`} role="img"
      aria-label={`${band} group among ${size.toLocaleString()} ongoing loans; this is not a probability of default`}>
      <div className="loan-risk-track"><span className="loan-risk-marker" /></div>
      <div className="loan-risk-labels"><span>Lower</span><span>Middle</span><span>Higher</span></div>
    </div>
  );
}

export default function AccountInsights({ baseline }) {
  const stress = baseline?.stress;
  if (!stress) return null;

  const reverse = stress.reverse_stress;
  const drift = stress.spending_drift;
  const buffer = stress.buffer_status;
  const income = stress.income_trend;
  const balance = stress.balance_trend;
  const peer = baseline.peer_context;
  const watch = baseline.watchlist;
  const pension = baseline.pension_check;
  const loanRisk = stress.loan_risk;
  const maxHistoricalSpending = Math.max(drift.recent_three_months || 0, drift.same_months_prior_year || 0, 1);
  const latestRatio = buffer.latest_to_buffer_ratio;
  const reverseLabel = reverse.maximum_income_loss_pct != null
    ? `Income could fall by up to ${reverse.maximum_income_loss_pct}%`
    : reverse.zero_income_coverage
      ? 'Savings could cover 6 months with no income'
      : 'Savings may not cover 6 months of a shortfall';
  // The meter's fill: the survivable income loss, or full when even zero income is covered.
  const maxLoss = reverse.maximum_income_loss_pct ?? (reverse.zero_income_coverage ? 100 : null);
  const negativeRate = stress.observations ? 100 * stress.negative_month_count / stress.observations : 0;
  const loanBand = loanRisk?.available ? loanRisk.band.replace(' relative ranking', '') : '';

  return (
    <section className="account-insights" aria-labelledby="account-insights-title">
      <div className="insight-heading">
        <div>
          <p className="eyebrow">PAST ACCOUNT ACTIVITY</p>
          <h2 id="account-insights-title">A closer look at this account</h2>
        </div>
        <span>{stress.observations.toLocaleString()} months on record. Latest: {stress.last_month}</span>
      </div>

      <div className="account-signal-grid">
        <Signal label="How much could income fall for 6 months?" value={reverseLabel}
          detail={`More savings needed for 6 months with income cut in half: ${cash(reverse.additional_buffer_for_target)}`}
          tone={!reverse.baseline_coverage && !reverse.zero_income_coverage ? 'warning' : ''}>
          {maxLoss != null
            ? <Meter fill={maxLoss} marks={[50]} scale={['0% income loss', '50% target', '100%']}
                label={`Income could fall by ${maxLoss}% before six months of savings run out; the mark is the 50% target`} />
            : <span className="meter-status">No positive stress margin</span>}
        </Signal>
        <Signal label="Spent in the last 3 months" value={drift.available ? cash(drift.recent_three_months) : 'Not enough history'}
          detail={drift.available
            ? `Same 3 months last year: ${cash(drift.same_months_prior_year)}${drift.flag ? '. Spending is much higher.' : '.'}`
            : 'No complete prior-year comparison'}
          tone={drift.flag ? 'warning' : ''} />
        <Signal label="Current savings compared with usual" value={buffer.available ? pct(latestRatio) : 'Not available'}
          detail={buffer.available
            ? `${cash(buffer.latest_month_end_balance)} at the latest month-end. Usual average: ${cash(buffer.baseline_buffer)}.`
            : 'The usual average savings balance is zero or below.'}
          tone={buffer.below_half ? 'warning' : ''}>
          {buffer.available && (
            <Meter fill={latestRatio * 100} marks={[25, 50]} scale={['0', '50% review mark', '100%']}
              label={`Latest balance is ${pct(latestRatio)} of the usual buffer; marks at 25% and 50%`} />
          )}
        </Signal>
        <Signal label="Money received each month, recently" value={cash(income.recent_3_month_median)}
          detail={`Usual monthly amount across all records: ${cash(income.official_full_history_median)}.${income.median_overstates_recent ? ' Recent income is much lower.' : ''}`}
          tone={income.median_overstates_recent ? 'warning' : ''} />
      </div>

      <div className="insight-detail-grid">
        <article className="insight-detail">
          <h3>What the past records show</h3>
          <dl className="insight-facts">
            <div><dt>Months when the account went below $0</dt><dd>{stress.negative_month_count}
              <FactMeter value={negativeRate} warning={stress.negative_month_count > 0}
                label={`${negativeRate.toFixed(1)}% of recorded months went below $0`} /></dd></div>
            <div><dt>Lowest recorded account balance</dt><dd>{cash(stress.worst_observed_balance)}</dd></div>
            <div><dt>Average balance change in the last 3 months</dt><dd>{balance.recent_vs_prior_3_month_mean_change == null
              ? 'Not enough history'
              : balance.recent_vs_prior_3_month_mean_change < 0
                ? `Down ${cash(Math.abs(balance.recent_vs_prior_3_month_mean_change))}`
                : balance.recent_vs_prior_3_month_mean_change > 0
                  ? `Up ${cash(balance.recent_vs_prior_3_month_mean_change)}`
                  : 'About the same'}</dd></div>
            <div><dt>Money taken out as cash</dt><dd>{stress.cash_withdrawal_share == null
              ? 'No cash withdrawal data recorded'
              : <>{pct(stress.cash_withdrawal_share)} of recorded spending
                <FactMeter value={stress.cash_withdrawal_share * 100} label={`${pct(stress.cash_withdrawal_share)} of recorded money out was cash withdrawals`} /></>}</dd></div>
            <div><dt>Loan on record</dt><dd>{loanStatus(stress.loan_status)}</dd></div>
            <div><dt>Scheduled monthly loan payment</dt><dd>{cash(stress.loan_contract_monthly_payment)}</dd></div>
            <div><dt>Typical monthly payment in the records</dt><dd>{cash(stress.median_observed_loan_payment)}</dd></div>
          </dl>
          <small className="insight-explainer">Cash withdrawals may be needed for everyday spending, so they are not treated as optional. The recorded loan payment can be $0 when payments are intermittent.</small>
        </article>

        <article className="insight-detail">
          <h3>Compared with similar accounts</h3>
          {peer && <>
            <p className="peer-percentile">{Math.round(peer.runway_percentile)}%<small> of similar accounts</small></p>
            <p>Savings last longer than for about {Math.round(peer.runway_percentile)}% of {peer.peer_count.toLocaleString()} accounts with similar income and pension patterns.</p>
            <div className="peer-track" role="img" aria-label={`Savings last longer than for ${Math.round(peer.runway_percentile)}% of similar accounts`}>
              <span style={{ width: `${clamp(peer.runway_percentile)}%` }} />
            </div>
            <div className="meter-scale"><span>Shorter runway</span><span>Longer runway</span></div>
            <small>A higher percentage means savings last longer than for more similar accounts.{peer.peer_capped_share != null && ` ${peer.peer_capped_share}% of this group is shown at the 120-month cap.`}</small>
          </>}
          <div className="watchlist-status">
            <strong>{watch.eligible ? `Past-account comparison: ${watch.band}` : 'Not included in the past-account comparison'}</strong>
            <span>Compared with {watch.eligible_accounts.toLocaleString()} accounts that never went below $0. Groups use past balances and cash flow. They do not predict the future.</span>
          </div>
          {pension && <p className="insight-callout">
            Most income is pension. {pension.ei55_runway_status === 'no_shortfall'
              ? 'Money coming in still covers spending when reduced to 55% of its usual level.'
              : `Savings last ${pension.ei55_runway_months} months when income is reduced to 55% of its usual level.`}
            Employment Insurance does not apply to pension income.
          </p>}
        </article>
      </div>

      {loanRisk?.available && (
        <article className="loan-indicator-card" aria-labelledby="loan-indicator-title">
          <div className="loan-indicator-heading">
            <div>
              <p className="eyebrow">EARLY RESEARCH ONLY</p>
              <h3 id="loan-indicator-title">How this loan compares with past loans</h3>
            </div>
            <strong>{loanBand} group</strong>
          </div>
          <LoanRiskScale band={loanBand} size={loanRisk.comparison_group_size} />
          <p>
            Before this loan began, the account history was compared with {loanRisk.comparison_group_size.toLocaleString()} other active loans.
            This grouping does not predict whether someone will repay and is not advice about this loan.
          </p>
          <small>The comparison uses three full months of records before each loan began. It includes {loanRisk.completed_training_loans.toLocaleString()} completed loans, of which {loanRisk.completed_defaults.toLocaleString()} were recorded as unpaid. This research has not been tested for making decisions.</small>
        </article>
      )}

      {drift.available && (
        <section className="drift-comparison" aria-label="Recent spending comparison">
          <div><span>Same 3 months last year</span><i><b style={{ width: `${drift.same_months_prior_year / maxHistoricalSpending * 100}%` }} /></i><strong>{cash(drift.same_months_prior_year)}</strong></div>
          <div><span>Last 3 months</span><i><b className="recent" style={{ width: `${drift.recent_three_months / maxHistoricalSpending * 100}%` }} /></i><strong>{cash(drift.recent_three_months)}</strong></div>
        </section>
      )}

      <div className="history-visuals">
        <MonthlyHistory rows={stress.monthly_history} />
        <BalanceHistory rows={stress.monthly_history} />
      </div>
    </section>
  );
}

